Rule.Source:
  import org.apache.log4j.Logger;

  import sailpoint.api.SailPointContext;
  import sailpoint.api.SailPointFactory;
  import sailpoint.object.Filter;
  import sailpoint.object.Identity;
  import sailpoint.object.QueryOptions;
  import sailpoint.tools.GeneralException;
  import sailpoint.tools.Util;

  Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
  if (logger.isTraceEnabled()) {
    logger.trace("Entered to IAMCOE_EMAIL_ATTRIBUTE_RULE!!!");
  }
  String finalEmail = null;
  finalEmail = identity.getEmail();
  logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> Mail from user : "+finalEmail);
  if (finalEmail != null) {
    logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> FinalEmail (We are in 1) : "+finalEmail);
    return finalEmail;
  }

  String firstName = identity.getFirstname();
  String lastName = identity.getLastname();
  logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> Firstname from user : "+firstName);
  logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> Lastname from user : "+lastName);
  if (Util.isNotNullOrEmpty(firstName) && Util.isNotNullOrEmpty(lastName)) {
    String domain = "@coe.com";
    String initialEmail = firstName +"."+ lastName;
    finalEmail = initialEmail + domain;
    logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> InitialEmail : "+initialEmail);

    QueryOptions queryOptions = new QueryOptions();
    Filter filter1 = Filter.ignoreCase(Filter.like("email", initialEmail, Filter.MatchMode.START));
    queryOptions.add(filter1);
    int totalObjects = context.countObjects(Identity.class, queryOptions);
    logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> TotalObjects of Filter1 : "+totalObjects);

    if (totalObjects == 0) {
      logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> FinalEmail (We are in 2) : "+finalEmail);
      return finalEmail;
    }
    else {
      int count = totalObjects;
      do {
        finalEmail = initialEmail +String.valueOf(count)+ domain;
        Filter filter2 = Filter.ignoreCase(Filter.eq("email", finalEmail));
        queryOptions.add(filter2);
        totalObjects = context.countObjects(Identity.class, queryOptions);
        logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> TotalObjects of Filter2 : "+totalObjects);
        count++;
      }
      while (totalObjects > 0);
      logger.debug("IAMCOE_EMAIL_ATTRIBUTE_RULE -> FinalEmail (We are in 3) : "+finalEmail);
      return finalEmail;
    }
  }
  if (logger.isTraceEnabled()) {
    logger.trace("IAMCOE_EMAIL_ATTRIBUTE_RULE Ended!!!");
  }
